// EZOrquestra — built-in orchestral sampler. Plays freely-licensed sample
// libraries (first target: the Alpine Project's WAV layout — per-note
// files with note/articulation/dynamics encoded in their names). Programs
// are JSON files (auto-generated by scanLibrary) with per-sample root
// notes, velocity layers and round-robin groups.
#pragma once

#include <juce_audio_processors/juce_audio_processors.h>

namespace cadence { class Engine; }

namespace ezorq {

juce::AudioProcessor* create();

// Goertzel + harmonic-coverage pitch detector. detectPitchHzEx also
// reports how much peak power the measured series explains versus the
// label's series (cov ratio >= 1.3 = the label is really mislabeled).
double detectPitchHzEx(const float* data, int numSamples, double sampleRate,
                       double labelHz, double* covMeasuredOut,
                       double* covLabelOut);
double detectPitchHz(const float* data, int numSamples, double sampleRate);

// Bounded wait until every live EZOrquestra has finished decoding its
// program (used by offline renders, which start immediately after the
// instances are created).
void waitProgramsLoaded();

// Scans an Alpine-Project-style root (Strings/Brass/Woodwinds with per-note
// sample files) and writes one JSON program per instrument+articulation
// into outDir. Returns the number of programs written.
int scanLibrary(const juce::File& root, const juce::File& outDir);

// Test hook: force EVERY subsequently-created instance to load this program
// index (bypassing the default flute). -1 restores the default.
void setProbeProgram(int index);

// Drops every cached decoded program (frees memory between test programs).
void clearProgramCache();

// Root-note range of the first ready instance's loaded program (test hook).
bool probeRange(int* lo, int* hi);

} // namespace ezorq
